22			out = append(out, page.Records...)
23			if page.Next == 0 {
24				break
25			}
26			page, err = s.AuditPage(page.Checkpoint, page.Next, 4, kind, subject)
27			if err != nil {
28				t.Fatalf("AuditPage: %v", err)
29			}
30		}
31		return out
32	}
