41		recs := drainAudit(t, s, "acme", "", "")
42		if len(recs) != 1 {
43			t.Fatalf("records = %d, want 1", len(recs))
44		}
45		r := recs[0]
46		if r.Org != "acme" || r.Seq != 1 || r.Kind != AuditPolicyChange {
47			t.Fatalf("bad record header: %+v", r)
48		}
49		if r.Change == nil || r.Change.Version != v || r.Change.RolledBack || r.Change.SourceVersion != 0 {
50			t.Fatalf("bad change payload: %+v", r.Change)
51		}
52		if !reflect.DeepEqual(r.Change.Policies, policies) {
53			t.Fatalf("stored policies = %+v, want %+v", r.Change.Policies, policies)
54		}
55		if r.PrevFingerprint == "" || r.Fingerprint == "" || r.PrevFingerprint == r.Fingerprint {
56			t.Fatalf("fingerprints not populated: %+v", r)
57		}
58	}
