60	func TestRollbackRecordNamesSourceVersion(t *testing.T) {
61		s := NewStore()
62		v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
63		if _, err := s.Publish("acme", v1, nil); err != nil {
64			t.Fatal(err)
65		}
